// server/services/milestone.service.ts
var MilestoneService = class {
  constructor(prisma) {
    this.prisma = prisma;
  }
  /**
   * Get all claimed milestone keys for a student
   */
  async getStudentClaims(studentId) {
    const claims = await this.prisma.studentMilestoneClaim.findMany({
      where: { studentId },
      select: { milestoneKey: true }
    });
    return claims.map((c) => c.milestoneKey);
  }
  /**
   * Atomically claim a milestone for a student
   * Returns { isFirstClaim: true, claim } if newly claimed, or { isFirstClaim: false } if already existed
   */
  async claimMilestone(studentId, milestoneKey) {
    if (!milestoneKey || typeof milestoneKey !== "string") {
      throw new Error("milestoneKey l\xE0 b\u1EAFt bu\u1ED9c");
    }
    try {
      const claim = await this.prisma.studentMilestoneClaim.create({
        data: {
          studentId,
          milestoneKey
        }
      });
      return { isFirstClaim: true, claim };
    } catch (error) {
      if (error.code === "P2002") {
        const existing = await this.prisma.studentMilestoneClaim.findUnique({
          where: {
            studentId_milestoneKey: {
              studentId,
              milestoneKey
            }
          }
        });
        return { isFirstClaim: false, claim: existing };
      }
      throw error;
    }
  }
};

// server/routes/milestone.routes.ts
async function milestoneRoutes(fastify) {
  const service = new MilestoneService(fastify.prisma);
  fastify.get("/claims", { preHandler: authenticate }, async (request, reply) => {
    try {
      const studentId = request.user.id;
      const claimedKeys = await service.getStudentClaims(studentId);
      return reply.send({ success: true, data: claimedKeys, claimedKeys });
    } catch (err) {
      return reply.status(500).send({ error: err.message });
    }
  });
  fastify.post(
    "/claim",
    { preHandler: authenticate },
    async (request, reply) => {
      try {
        const studentId = request.user.id;
        const { milestoneKey } = request.body || {};
        if (!milestoneKey) {
          return reply.status(400).send({ error: "milestoneKey l\xE0 b\u1EAFt bu\u1ED9c" });
        }
        const result = await service.claimMilestone(studentId, milestoneKey);
        return reply.status(result.isFirstClaim ? 201 : 200).send({
          success: true,
          isFirstClaim: result.isFirstClaim,
          claim: result.claim
        });
      } catch (err) {
        return reply.status(500).send({ error: err.message });
      }
    }
  );
}

// server/routes/referrals.routes.ts
var referralsRoutes = async (fastify) => {
  fastify.get("/validate-code/:code", async (request, reply) => {
    const { code } = request.params;
    const cleanCode = (code || "").trim().toUpperCase();
    if (!cleanCode || cleanCode.length < 5) {
      return reply.status(400).send({ valid: false, message: "M\xE3 gi\u1EDBi thi\u1EC7u kh\xF4ng h\u1EE3p l\u1EC7" });
    }
    const inviter = await fastify.prisma.user.findUnique({
      where: { referralCode: cleanCode },
      select: {
        userId: true,
        fullName: true,
        avatarUrl: true
      }
    });
    if (!inviter) {
      return reply.status(404).send({ valid: false, message: "M\xE3 gi\u1EDBi thi\u1EC7u kh\xF4ng t\u1ED3n t\u1EA1i" });
    }
    return {
      valid: true,
      referralCode: cleanCode,
      inviterName: inviter.fullName || "H\u1ECDc vi\xEAn ARIS",
      inviterAvatar: inviter.avatarUrl
    };
  });
  fastify.get(
    "/my-referrals",
    { preHandler: [authenticate] },
    async (request, reply) => {
      const user = request.user;
      if (!user?.id) {
        return reply.status(401).send({ error: "Unauthorized" });
      }
      let profile = await fastify.prisma.user.findUnique({
        where: { userId: user.id },
        select: {
          id: true,
          userId: true,
          fullName: true,
          referralCode: true
        }
      });
      if (!profile) {
        return reply.status(404).send({ error: "User profile not found" });
      }
      if (!profile.referralCode) {
        const cleanName = (profile.fullName || "STUDENT").toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^A-Z]/g, "").slice(0, 5).padEnd(5, "X");
        const idSuffix = profile.userId.replace(/-/g, "").slice(-4).toUpperCase();
        let code = `ARIS-${cleanName}${idSuffix}`;
        try {
          profile = await fastify.prisma.user.update({
            where: { userId: profile.userId },
            data: { referralCode: code },
            select: {
              id: true,
              userId: true,
              fullName: true,
              referralCode: true
            }
          });
        } catch {
          code = `ARIS-${cleanName}${Math.floor(1e3 + Math.random() * 9e3)}`;
          profile = await fastify.prisma.user.update({
            where: { userId: profile.userId },
            data: { referralCode: code },
            select: {
              id: true,
              userId: true,
              fullName: true,
              referralCode: true
            }
          });
        }
      }
      const [attributions, rewards] = await Promise.all([
        fastify.prisma.referralAttribution.findMany({
          where: { inviterUserId: user.id },
          include: {
            referee: {
              select: {
                fullName: true,
                avatarUrl: true,
                createdAt: true
              }
            }
          },
          orderBy: { createdAt: "desc" }
        }),
        fastify.prisma.referralReward.findMany({
          where: { inviterUserId: user.id },
          orderBy: { createdAt: "desc" }
        })
      ]);
      const totalInvited = attributions.length;
      const totalEligible = rewards.filter((r) => r.status === "ELIGIBLE").length;
      const totalDelivered = rewards.filter((r) => r.status === "DELIVERED").length;
      return {
        referralCode: profile.referralCode,
        stats: {
          totalInvited,
          totalEligible,
          totalDelivered
        },
        attributions: attributions.map((a) => ({
          id: a.id,
          refereeName: a.referee?.fullName || "B\u1EA1n \u0111\u1ED3ng h\xE0nh",
          refereeAvatar: a.referee?.avatarUrl,
          discountAmount: Number(a.discountAmount),
          status: a.status,
          createdAt: a.createdAt
        })),
        rewards: rewards.map((r) => ({
          id: r.id,
          attributionId: r.attributionId,
          rewardType: r.rewardType,
          status: r.status,
          qualifiedAt: r.qualifiedAt,
          deliveredAt: r.deliveredAt,
          notes: r.notes,
          createdAt: r.createdAt
        }))
      };
    }
  );
};
